// Code node mode: Run Once for All Items
// DEBUG = false: hanya keluarkan baris Pending yang sudah jatuh tempo.
// DEBUG = true : keluarkan semua baris beserta alasan kenapa diproses/dilewati.
const DEBUG = true;
const ZONE = 'Asia/Jakarta';
const items = $input.all();
const now = DateTime.now().setZone(ZONE);

function normalizeKey(value) {
  return String(value ?? '').trim().toLowerCase().replace(/[\s_-]+/g, '');
}

function getField(row, fieldName) {
  const wanted = normalizeKey(fieldName);
  const key = Object.keys(row).find(k => normalizeKey(k) === wanted);
  return key === undefined ? undefined : row[key];
}

function invalidDate() {
  return DateTime.invalid('Unrecognized date/time value');
}

function parseDate(value) {
  if (value === undefined || value === null || String(value).trim() === '') return invalidDate();

  // Google Sheets serial date: integer days since 1899-12-30.
  if (typeof value === 'number' && Number.isFinite(value)) {
    const base = DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone: ZONE });
    return base.plus({ days: Math.floor(value) }).startOf('day');
  }

  if (value instanceof Date) {
    const parsed = DateTime.fromJSDate(value, { zone: ZONE });
    return parsed.isValid ? parsed.startOf('day') : invalidDate();
  }

  const s = String(value).trim();
  const iso = DateTime.fromISO(s, { zone: ZONE });
  if (iso.isValid) return iso.startOf('day');

  // Prioritas format Indonesia: dd/MM/yyyy, kemudian format umum lainnya.
  const formats = [
    'd/M/yyyy', 'dd/MM/yyyy',
    'd-M-yyyy', 'dd-MM-yyyy',
    'yyyy/M/d', 'yyyy-MM-dd',
    'M/d/yyyy', 'MM/dd/yyyy',
    'd.M.yyyy', 'dd.MM.yyyy'
  ];
  for (const format of formats) {
    const parsed = DateTime.fromFormat(s, format, { zone: ZONE, locale: 'en' });
    if (parsed.isValid) return parsed.startOf('day');
  }

  // Numeric serial date sometimes arrives as a string.
  if (/^\d+(?:\.\d+)?$/.test(s)) {
    const serial = Number(s);
    if (Number.isFinite(serial) && serial >= 1) {
      const base = DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone: ZONE });
      return base.plus({ days: Math.floor(serial) }).startOf('day');
    }
  }
  return invalidDate();
}

function parseTime(value) {
  if (value === undefined || value === null || String(value).trim() === '') return null;

  // Google Sheets time serial: fraction of a 24-hour day (e.g. 0.5 = 12:00).
  if (typeof value === 'number' && Number.isFinite(value) && value >= 0 && value < 1) {
    let seconds = Math.round(value * 86400) % 86400;
    return {
      hour: Math.floor(seconds / 3600),
      minute: Math.floor((seconds % 3600) / 60),
      second: seconds % 60,
      millisecond: 0
    };
  }

  let s = String(value).trim();
  if (/^\d+(?:\.\d+)?$/.test(s)) {
    const numeric = Number(s);
    if (Number.isFinite(numeric) && numeric >= 0 && numeric < 1) {
      let seconds = Math.round(numeric * 86400) % 86400;
      return {
        hour: Math.floor(seconds / 3600),
        minute: Math.floor((seconds % 3600) / 60),
        second: seconds % 60,
        millisecond: 0
      };
    }
  }

  if (/^\d{1,2}\.\d{2}(?:\.\d{2})?$/.test(s)) s = s.replace(/\./g, ':');
  const upper = s.toUpperCase().replace(/\s+/g, ' ');
  const iso = DateTime.fromISO(`1970-01-01T${s}`, { zone: ZONE });
  if (iso.isValid) {
    return { hour: iso.hour, minute: iso.minute, second: iso.second, millisecond: iso.millisecond };
  }

  const formats = [
    'H:mm', 'HH:mm', 'H:mm:ss', 'HH:mm:ss',
    'h:mm a', 'hh:mm a', 'h:mm:ss a', 'hh:mm:ss a',
    'h a', 'hh a'
  ];
  for (const format of formats) {
    const parsed = DateTime.fromFormat(upper, format, { zone: ZONE, locale: 'en' });
    if (parsed.isValid) {
      return { hour: parsed.hour, minute: parsed.minute, second: parsed.second, millisecond: parsed.millisecond };
    }
  }
  return null;
}

function describeDateTime(dt) {
  return dt && dt.isValid ? dt.toISO() : null;
}

if (items.length === 0) {
  return DEBUG ? [{ json: { _schedulerDebug: 'Tidak ada item masuk dari Google Sheets. Periksa output node Get row(s) in sheet.' } }] : [];
}

const dueItems = [];
const debugItems = [];

items.forEach((item, index) => {
  const row = item.json ?? {};
  const rawStatus = getField(row, 'Status');
  const rawDate = getField(row, 'Scheduled Date');
  const rawTime = getField(row, 'Scheduled Time');
  const status = String(rawStatus ?? '').trim().toLowerCase();
  const date = parseDate(rawDate);
  const time = parseTime(rawTime);

  let scheduled = null;
  let reason = '';
  let isDue = false;

  if (status !== 'pending') {
    reason = `Status bukan Pending (nilai terbaca: ${String(rawStatus ?? '(kosong)')})`;
  } else if (rawDate === undefined || rawDate === null || String(rawDate).trim() === '') {
    reason = 'Kolom Scheduled Date kosong/tidak ditemukan. Periksa nama header di Google Sheets.';
  } else if (!date.isValid) {
    reason = `Scheduled Date tidak bisa diparse: ${String(rawDate)}`;
  } else if (rawTime === undefined || rawTime === null || String(rawTime).trim() === '') {
    reason = 'Kolom Scheduled Time kosong/tidak ditemukan. Periksa nama header di Google Sheets.';
  } else if (!time) {
    reason = `Scheduled Time tidak bisa diparse: ${String(rawTime)}`;
  } else {
    scheduled = date.set(time).setZone(ZONE);
    isDue = scheduled.isValid && scheduled.toMillis() <= now.toMillis();
    reason = !scheduled.isValid
      ? 'Gabungan tanggal dan waktu tidak valid.'
      : isDue
        ? 'READY: status Pending dan jadwal sudah jatuh tempo.'
        : `Belum waktunya; jadwal ${scheduled.toFormat('yyyy-LL-dd HH:mm:ss')} WIB, sekarang ${now.toFormat('yyyy-LL-dd HH:mm:ss')} WIB.`;
  }

  if (isDue) dueItems.push(item);

  if (DEBUG) {
    debugItems.push({
      json: {
        ...row,
        _schedulerDebug: {
          inputItem: index,
          statusRead: rawStatus ?? null,
          scheduledDateRead: rawDate ?? null,
          scheduledTimeRead: rawTime ?? null,
          parsedScheduledAt: describeDateTime(scheduled),
          nowJakarta: now.toISO(),
          isDue,
          reason
        }
      },
      pairedItem: { item: index }
    });
  }
});

return DEBUG ? debugItems : dueItems;
